 let point=zones[d.zone];if(d.zone==='custom'){const lat=Number(d.lat),lng=Number(d.lng);if(!d.lat||!d.lng||!Number.isFinite(lat)||!Number.isFinite(lng)||Math.abs(lat)>90||Math.abs(lng)>180)throw Error('Completa coordenadas válidas para el punto manual.');point={lat,lng,name:d.label?.trim()||'Punto elegido manualmente'};}
